<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';
use App\Config;use App\Database;use App\Logger;use App\McpAuth;use App\McpServer;use App\OrderService;use App\TelegramGateway;
final class FakeTelegram implements TelegramGateway {
 public array $sent=[]; public int $downloads=0; public bool $failNextSend=false;
 public function sendMessage(string $chatId,string $text): void {if($this->failNextSend){$this->failNextSend=false;throw new RuntimeException('simulated Telegram failure');}$this->sent[]=['chat'=>$chatId,'text'=>$text];}
 public function download(string $fileId,string $target,int $maxBytes): array {$this->downloads++;$bytes=base64_decode('UklGRiQAAABXQVZFZm10IBAAAAABAAEARKwAAESsAAABAAgAZGF0YQAAAAA=');file_put_contents($target,$bytes);return ['bytes'=>strlen($bytes),'telegram_file_size'=>strlen($bytes)];}
}
$passed=0;$failed=0;
function check(string $name,callable $fn): void {global $passed,$failed;try{$fn();$passed++;echo "PASS $name\n";}catch(Throwable $e){$failed++;echo "FAIL $name: ".$e->getMessage()."\n";}}
function ok(bool $condition,string $message='assertion failed'): void {if(!$condition)throw new RuntimeException($message);}
function throws(callable $fn): Throwable {try{$fn();}catch(Throwable $e){return $e;}throw new RuntimeException('Expected exception was not thrown.');}
function setupService(?string $dbPath=null,?FakeTelegram $tg=null): array {$root=sys_get_temp_dir().'/voice-mcp-'.bin2hex(random_bytes(4));$storage=$root.'/audio';@mkdir($storage,0700,true);$path=$dbPath??$root.'/orders.sqlite';$pdo=(new Database($path))->pdo();$cfg=new Config('https://voice.test',str_repeat('a',40),'test-token',str_repeat('b',40),str_repeat('c',40),$path,$storage,$root.'/app.log',1024,300,7);$fake=$tg??new FakeTelegram();return [new OrderService($pdo,$cfg,$fake,new Logger($root.'/app.log')),$pdo,$cfg,$fake,$root];}
function insertOrder(PDO $pdo,string $id,string $audioPath,string $status='pending',int $update=1,string $transcript=''): void {$now=time();$q=$pdo->prepare('INSERT INTO orders(id,update_id,chat_id,telegram_user_id,telegram_file_id,audio_path,mime_type,byte_size,duration_seconds,status,transcript,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$id,$update,'9001','8001','file-x',$audioPath,'audio/wav',44,2,$status,$transcript?:null,$now,$now]);}
check('MCP rejects missing and incorrect bearer tokens',function(){ok(!McpAuth::authorized('','secret'));ok(!McpAuth::authorized('Bearer wrong','secret'));ok(McpAuth::authorized('Bearer secret','secret'));});
check('duplicate Telegram update creates only one order',function(){[$s,$pdo,$cfg,$tg]=setupService();$u=['update_id'=>23,'message'=>['chat'=>['id'=>9001],'from'=>['id'=>8001],'voice'=>['file_id'=>'abc','mime_type'=>'audio/wav','duration'=>3,'file_size'=>44]]];$id=$s->receive($u);ok($id===$s->receive($u));ok($tg->downloads===1);});
check('invalid file type is rejected',function(){[$s]=setupService();$e=throws(fn()=>$s->receive(['update_id'=>1,'message'=>['chat'=>['id'=>1],'audio'=>['file_id'=>'x','mime_type'=>'video/mp4','duration'=>1,'file_size'=>1]]]));ok($e instanceof InvalidArgumentException);});
check('oversized and too-long recordings are rejected',function(){[$s]=setupService();foreach([['audio/wav',2,1025],['audio/wav',301,44]] as [$mime,$duration,$size]){$e=throws(fn()=>$s->receive(['update_id'=>$duration,'message'=>['chat'=>['id'=>1],'voice'=>['file_id'=>'x','mime_type'=>$mime,'duration'=>$duration,'file_size'=>$size]]]));ok($e instanceof InvalidArgumentException);}});
check('invalid order ID is rejected',function(){[$s]=setupService();ok(throws(fn()=>$s->claim('../bad')) instanceof InvalidArgumentException);});
check('missing audio file is marked failed',function(){[$s,$pdo]=setupService();$id=str_repeat('d',32);insertOrder($pdo,$id,'/tmp/does-not-exist-'.bin2hex(random_bytes(3)));throws(fn()=>$s->claim($id));$q=$pdo->prepare('SELECT status FROM orders WHERE id=?');$q->execute([$id]);ok($q->fetchColumn()==='failed');});
check('repeat transcript submission does not redeliver',function(){[$s,$pdo,$cfg,$tg]=setupService();$id=str_repeat('e',32);$path=$cfg->storagePath.'/'.$id.'.wav';file_put_contents($path,'audio');insertOrder($pdo,$id,$path);$o=$s->claim($id);$a=$s->submit($id,$o['lease_token'],'hello world','en');$b=$s->submit($id,$o['lease_token'],'hello world','en');ok($a['delivery_status']==='sent'&&$b['delivery_status']==='sent');ok(count($tg->sent)===1);ok(throws(fn()=>$s->submit($id,$o['lease_token'],'different transcript')) instanceof RuntimeException);});
check('Telegram delivery failure is recorded and retryable',function(){[$s,$pdo,$cfg,$tg]=setupService();$id=str_repeat('f',32);$path=$cfg->storagePath.'/'.$id.'.wav';file_put_contents($path,'audio');insertOrder($pdo,$id,$path);$o=$s->claim($id);$tg->failNextSend=true;$first=$s->submit($id,$o['lease_token'],'retry me');ok($first['delivery_status']==='failed');$second=$s->submit($id,$o['lease_token'],'retry me');ok($second['delivery_status']==='sent');ok(count($tg->sent)===1);});
check('long transcript is split under Telegram message limit',function(){$parts=OrderService::splitText(str_repeat('word ',3000),3500);ok(count($parts)>1);foreach($parts as $p)ok(mb_strlen($p)<=3500);});
check('two workers cannot claim the same order at once',function(){[$s1,$pdo,$cfg,$tg,$root]=setupService();$id=str_repeat('a',32);$path=$cfg->storagePath.'/'.$id.'.wav';file_put_contents($path,'audio');insertOrder($pdo,$id,$path);$s2=new OrderService(new PDO('sqlite:'.$cfg->dbPath,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]),$cfg,$tg,new Logger($root.'/app.log'));$first=$s1->claim($id);ok(strlen($first['lease_token'])===48);ok(throws(fn()=>$s2->claim($id)) instanceof RuntimeException);});
check('MCP handshake, tool listing, and audio content block work',function(){[$s,$pdo,$cfg,$tg]=setupService();$id=str_repeat('b',32);$path=$cfg->storagePath.'/'.$id.'.wav';$bytes=base64_decode('UklGRiQAAABXQVZFZm10IBAAAAABAAEARKwAAESsAAABAAgAZGF0YQAAAAA=');file_put_contents($path,$bytes);insertOrder($pdo,$id,$path);$mcp=new McpServer($s);$hello=$mcp->handle(['jsonrpc'=>'2.0','id'=>1,'method'=>'initialize','params'=>['protocolVersion'=>'2025-03-26','capabilities'=>[],'clientInfo'=>['name'=>'test','version'=>'1']]]);ok($hello['result']['protocolVersion']==='2025-03-26');$list=$mcp->handle(['jsonrpc'=>'2.0','id'=>2,'method'=>'tools/list']);ok(count($list['result']['tools'])===5);$order=$s->claim($id);$audio=$mcp->handle(['jsonrpc'=>'2.0','id'=>3,'method'=>'tools/call','params'=>['name'=>'get_audio','arguments'=>['order_id'=>$id,'lease_token'=>$order['lease_token']]]]);ok($audio['result']['content'][0]['type']==='audio');});
echo "\n$passed passed; $failed failed\n";exit($failed===0?0:1);
